# depth distance within component to boundary (outside grid or wall)
def depth_map(k):
 cells=set(comps[k]); d={}; q=collections.deque()
 for r,c in cells:
  if r in (0,n-1) or c in (0,n-1) or any((r+dr,c+dc) not in cells for dr,dc in ((1,0),(-1,0),(0,1),(0,-1))):
   d[(r,c)]=0;q.append((r,c))
 while q:
  x=q.popleft()
  for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
   y=(x[0]+dx,x[1]+dy)
   if y in cells and y not in d: d[y]=d[x]+1;q.append(y)
 return d
for k,cells in enumerate(comps):
 d=depth_map(k)
 print(k,[(r,c,int(a[r,c]),d[(r,c)]) for r,c in cells if a[r,c]!=1], 'maxd',max(d.values()))

out=a.copy()
for k,cells in enumerate(comps):
 seeds={}
 for r,c in cells:
  if a[r,c] != 1: seeds[depth_map(k)[(r,c)]]=int(a[r,c])
 if not seeds: continue
 # order depth 0 outward inward; use cyclic sequence if multiple, uniform single
 seq=[seeds[d] for d in sorted(seeds)]
 dmap=depth_map(k)
 for r,c in cells:
  out[r,c]=seq[dmap[(r,c)]%len(seq)]
print('\n'.join(' '.join(map(str,row)) for row in out))

